//! ELIZA-style conversation script schema — TOML-serializable.
//!
//! Defines the data model for Phase 0 ELIZA scripts generated by the
//! [`psyche_compiler`]. Keywords are checked in descending priority order;
//! the first matching decomposition fires and cycles through its reassemblies.
//!
//! ## TOML wire format (excerpt)
//!
//! ```toml
//! [meta]
//! name = "Scholar"
//! grammar = "narrative"
//! generated = true
//! version = "1"
//! reflection_depth = "moderate"
//! dominant_archetype = "sage"
//!
//! [defaults]
//! greetings = ["Greetings. I am Scholar. Let us begin."]
//! farewells  = ["Until next time."]
//! memory     = ["Can you elaborate?", "What else comes to mind?"]
//!
//! [[rules]]
//! keyword  = "know"
//! priority = 17
//! tags     = ["sage"]
//!
//! [[rules.decompositions]]
//! pattern       = "(.*)(know|knowledge|knowing)(.*)"
//! reassemblies  = ["What is it about $3 that you wish to understand better?"]
//! ```

use serde::{Deserialize, Serialize};

// ── Schema types ─────────────────────────────────────────────────────────

/// A complete ELIZA-style conversation script serializable to TOML.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ElizaScript {
    pub meta: ScriptMeta,
    pub defaults: DefaultResponses,
    #[serde(default)]
    pub rules: Vec<ElizaRule>,
}

/// Script metadata and generation provenance.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ScriptMeta {
    /// Display name matching the persona.
    pub name: String,
    /// Grammar preference: `"formal"`, `"narrative"`, or `"terse"`.
    pub grammar: String,
    /// `true` when auto-generated from a `Psyche`.
    pub generated: bool,
    /// Schema version — currently `"1"`.
    pub version: String,
    /// Reflection depth: `"surface"`, `"moderate"`, or `"deep"`.
    pub reflection_depth: String,
    /// Archetype that most influenced this script's rule set.
    pub dominant_archetype: String,
}

/// Fallback responses used when no rule fires.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct DefaultResponses {
    /// Opening phrases played at session start.
    pub greetings: Vec<String>,
    /// Closing phrases played at session end.
    pub farewells: Vec<String>,
    /// Memory responses cycled when no keyword matches user input.
    pub memory: Vec<String>,
}

/// One ELIZA rule: a keyword plus decomposition → reassembly pairs.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct ElizaRule {
    /// Trigger word checked against user input (case-insensitive substring).
    pub keyword: String,
    /// Higher priority rules are tried first. Range: 1–30.
    pub priority: u32,
    /// Archetype tags for this rule cluster (e.g. `["sage"]`).
    pub tags: Vec<String>,
    /// Decomposition patterns tried in order until one matches.
    pub decompositions: Vec<Decomposition>,
}

/// A decomposition pattern with its reassembly templates.
///
/// `pattern` is a regex where capture groups (`(.*)`) are referenced as
/// `$1`, `$2`, … in reassembly strings.  The engine cycles through
/// `reassemblies` in round-robin order.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Decomposition {
    /// Regex decomposition pattern. Capture groups become `$N` in reassemblies.
    pub pattern: String,
    /// Reassembly templates cycled in order.
    pub reassemblies: Vec<String>,
}
